const sellBookingSeats = `-- name: SellBookingSeats :many
UPDATE booking_seats SET status = 'sold'
WHERE booking_id = $1 AND status IN ('held', 'expired')
RETURNING id, company_id, booking_id, departure_id, seat_cell_id, seat_label, category_id, passenger_name, passenger_phone, base_price, category_surcharge, seat_surcharge, discount_amount, total_price, status, hold_expires_at, created_at, updated_at, early_bird_amount, from_seq, to_seq
`

// Passe les sièges en "vendu". Si un siège expiré a été repris entre-temps,
// l'index unique lève une violation : le paiement tardif part en remboursement.
func (q *Queries) SellBookingSeats(ctx context.Context, bookingID uuid.UUID) ([]BookingSeat, error) {
	rows, err := q.db.Query(ctx, sellBookingSeats, bookingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BookingSeat{}
	for rows.Next() {
		var i BookingSeat
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.BookingID,
			&i.DepartureID,
			&i.SeatCellID,
			&i.SeatLabel,
			&i.CategoryID,
			&i.PassengerName,
			&i.PassengerPhone,
			&i.BasePrice,
			&i.CategorySurcharge,
			&i.SeatSurcharge,
			&i.DiscountAmount,
			&i.TotalPrice,
			&i.Status,
			&i.HoldExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.EarlyBirdAmount,
			&i.FromSeq,
			&i.ToSeq,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

